const cleanArg=(v)=>{const t=String(v==null?'':v).trim();return /^\{[a-zA-Z0-9_]+\}$/.test(t)?'':t;};
const size=(cleanArg(arg0)||'wallpaper').toLowerCase();
const qft={large:'+filterui:imagesize-large',wallpaper:'+filterui:imagesize-wallpaper'}[size];
if(!qft)return {filtered:false,size:'any'};
const u=new URL(location.href);u.searchParams.set('qft',qft);
setTimeout(()=>location.assign(u.toString()),0);
return {filtered:true,size,target:u.toString()};

const cleanArg=(v)=>{const t=String(v==null?'':v).trim();return /^\{[a-zA-Z0-9_]+\}$/.test(t)?'':t;};
const n=parseInt(cleanArg(arg0),10);
const count=Number.isFinite(n)&&n>0?Math.min(n,500):100;
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
const collect=()=>{const seen=new Set();const items=[];for(const a of document.querySelectorAll('a.iusc[m]')){let m=null;try{m=JSON.parse(a.getAttribute('m')||'{}');}catch(e){continue;}const u=(m&&m.murl)||'';if(!/^https?:\/\//i.test(u)||seen.has(u))continue;let width=0,height=0;try{const h=new URL(a.getAttribute('href')||'',location.origin).searchParams;width=parseInt(h.get('expw'),10)||0;height=parseInt(h.get('exph'),10)||0;}catch(e){}if((minW&&width<minW)||(minH&&height<minH))continue;seen.add(u);items.push({title:(m.t||'').trim(),width,height,high_res_url:u,thumbnail_url:m.turl||'',source_page:m.purl||''});}return items;};
const minW=parseInt(cleanArg(arg1),10)||0;const minH=parseInt(cleanArg(arg2),10)||0;
const deadline=Date.now()+24000;
let items=collect();let stalls=0;
while(items.length<count&&Date.now()<deadline&&stalls<4){window.scrollTo(0,document.documentElement.scrollHeight);await sleep(1200);const more=document.querySelector('a.btn_seemore, .btn_seemore');if(more&&more.offsetParent)more.click();const next=collect();stalls=next.length>items.length?0:stalls+1;items=next;}
items=items.slice(0,count);
return {requested:count,items_count:items.length,image_urls:items.map(i=>i.high_res_url),items};
